DoubleCounter$Counter$raise_arg_error <- function(.mx_self, mode) {
  if (!isTRUE(is.character(mode))) .miniextendr_arg_error("mode", "must be character")
  if (!isTRUE(length(mode) == 1L)) .miniextendr_arg_error("mode", "must have length 1")
  .val <- .Call(C_consumer_pkg_DoubleCounter__Counter__raise_arg_error, .call = sys.call(), .mx_self, mode)
  if (inherits(.val, "rust_condition_value") && isTRUE(attr(.val, "__rust_condition__"))) return(.miniextendr_raise_condition(.val, sys.call()))
  .val
  .mx_self
}
attr(DoubleCounter$Counter$raise_arg_error, ".__mx_instance__") <- TRUE

